                // Ensure we make progress: consume at least one character.
                if (cb.position() == lastPosition) {
                    // No progress – abort to avoid infinite loop.
                    throw new IllegalStateException(
                            "Encoder stalled at position " + lastPosition +
                            ". Malformed/unmappable input detected.");
