/**
 * Renderer implementation that safely creates XSLT transformers.
 */
public class XsltRenderer implements Renderer {

    /* A single, securely configured TransformerFactory instance. */
    private static final TransformerFactory TRANSFORMER_FACTORY = createSecureFactory();

    /**
     * Creates a Transformer from the supplied XSLT template stream.
     *
     * @param templateStream the XSLT template as an InputStream
     * @return a Transformer ready for use
     * @throws IOException if the stream cannot be read or closed
     */
    private static Transformer createTransformer(InputStream templateStream) throws IOException {
        if (templateStream == null) {
            throw new IllegalArgumentException("Template stream must not be null");
        }

        try {
            // The StreamSource will consume the stream during transformer creation.
            return TRANSFORMER_FACTORY.newTransformer(new StreamSource(templateStream));
        } catch (TransformerConfigurationException e) {
            throw new ProcessingFailedException("Failed to create XSLT template", e);
        } finally {
            // Ensure the stream is always closed to avoid resource leaks.
            templateStream.close();
        }
    }

    /* --------------------------------------------------------------------- */
    /* Helper methods for secure configuration                               */
    /* --------------------------------------------------------------------- */

    /**
     * Instantiates and configures a TransformerFactory that enforces
     * secure processing rules to mitigate XSLT-based RCE attacks.
     *
     * @return a securely configured TransformerFactory
     */
    private static TransformerFactory createSecureFactory() {
        TransformerFactory factory = TransformerFactory.newInstance();

        try {
            // Enable the standard secure processing feature.
            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

            /*
             * Disable external DTDs and stylesheets to prevent
             * external entity resolution and loading of arbitrary
             * resources via the XSLT stylesheet.
             */
            factory.setAttribute(TransformerFactory.ACCESS_EXTERNAL_DTD, "");
            factory.setAttribute(TransformerFactory.ACCESS_EXTERNAL_STYLESHEET, "");
            factory.setAttribute(TransformerFactory.ACCESS_EXTERNAL_OUTPUT, "");

        } catch (IllegalArgumentException | UnsupportedOperationException | TransformerConfigurationException ex) {
            // If the underlying implementation does not support these
            // features, log a warning and proceed with caution.
            // In production, consider throwing a runtime exception instead.
            System.err.println("Warning: Unable to fully secure TransformerFactory: " + ex.getMessage());
        }

        return factory;
    }

    // other methods
}
