import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.apache.commons.compress.archivers.ArchiveEntry;

public class Expander {

    // other methods

    /**
     * Safely extracts archive entries into {@code targetDirectory}.  The method
     * performs rigorous path validation to prevent path‑traversal attacks.
     *
     * @param supplier      provides the next readable archive entry
     * @param writer        writes the entry data to an {@link OutputStream}
     * @param targetDirectory the directory into which the archive is expanded
     * @throws IOException if an I/O error occurs or a malicious entry is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the target directory to its real (canonical) path once.
        Path targetDirPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            // Reject null or empty names – they could be used to trick the
            // filesystem into creating unexpected files.
            if (entryName == null || entryName.isEmpty()) {
                throw new IOException("archive entry has no name");
            }

            // Reject absolute paths – they bypass the directory constraint.
            if (Paths.get(entryName).isAbsolute()) {
                throw new IOException("absolute entry name not allowed: " + entryName);
            }

            // Resolve the entry against the target directory and normalize
            // to collapse any ".." or "." components.
            Path entryPath = targetDirPath.resolve(entryName).normalize();

            // Ensure the resolved path is still within the target directory.
            if (!entryPath.startsWith(targetDirPath)) {
                throw new IOException(
                        "expanding " + entryName + " would create file outside of "
                                + targetDirectory);
            }

            // Convert back to File for legacy APIs.
            File f = entryPath.toFile();

            if (nextEntry.isDirectory()) {
                if (!f.isDirectory() && !f.mkdirs()) {
                    throw new IOException("failed to create directory " + f);
                }
            } else {
                // Ensure parent directories exist.
                Path parentPath = entryPath.getParent();
                if (parentPath != null && !Files.isDirectory(parentPath)) {
                    Files.createDirectories(parentPath);
                }

                // Write the file contents.
                try (OutputStream out = Files.newOutputStream(entryPath)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
