import javax.xml.XMLConstants;
import javax.xml.parsers.SAXParser;
import javax.xml.parsers.SAXParserFactory;
import javax.xml.transform.sax.SAXSource;
import javax.xml.transform.stream.StreamSource;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;
import org.xml.sax.XMLReader;
import org.apache.camel.Converter;
import org.apache.camel.Exchange;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Converter
public class XmlConverter {

    private static final Logger LOG = LoggerFactory.getLogger(XmlConverter.class);

    // other methods

    @Converter
    public SAXSource toSAXSourceFromStream(StreamSource source, Exchange exchange) throws SAXException {
        InputSource inputSource;
        if (source.getReader() != null) {
            inputSource = new InputSource(source.getReader());
        } else {
            inputSource = new InputSource(source.getInputStream());
        }
        inputSource.setSystemId(source.getSystemId());
        inputSource.setPublicId(source.getPublicId());

        SAXParserFactory sfactory = null;
        XMLReader xmlReader = null;

        try {
            // Prefer a factory supplied by Camel if available
            if (exchange != null) {
                sfactory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
            }
            if (sfactory == null) {
                sfactory = SAXParserFactory.newInstance();
            }

            // Configure the factory to disable all external entity processing
            configureFactory(sfactory);

            SAXParser parser = sfactory.newSAXParser();
            xmlReader = parser.getXMLReader();

            // Further tighten the reader configuration
            configureReader(xmlReader);

        } catch (Exception ex) {
            LOG.warn("Failed to create a secure SAXParser/XMLReader: {}", ex.toString(), ex);
            throw new SAXException("Unable to create a secure XMLReader", ex);
        }

        return new SAXSource(xmlReader, inputSource);
    }

    /**
     * Apply a set of security‑related features to the {@link SAXParserFactory}.
     */
    private void configureFactory(SAXParserFactory factory) {
        // Enable secure processing
        try {
            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        } catch (Exception e) {
            LOG.warn("SAXParserFactory does not support FEATURE_SECURE_PROCESSING: {}", e.toString(), e);
        }

        // Disable loading of external DTDs and grammars
        setFactoryFeature(factory, "http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        setFactoryFeature(factory, "http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);

        // Disable external entities
        setFactoryFeature(factory, "http://xml.org/sax/features/external-general-entities", false);
        setFactoryFeature(factory, "http://xml.org/sax/features/external-parameter-entities", false);

        // Common defensive settings
        factory.setNamespaceAware(true);
        factory.setValidating(false);
        factory.setXIncludeAware(false);
    }

    /**
     * Apply a set of security‑related features to the {@link XMLReader}.
     */
    private void configureReader(XMLReader reader) {
        // Disallow DOCTYPE declarations entirely
        setReaderFeature(reader, "http://apache.org/xml/features/disallow-doctype-decl", true);

        // Disable external entities
        setReaderFeature(reader, "http://xml.org/sax/features/external-general-entities", false);
        setReaderFeature(reader, "http://xml.org/sax/features/external-parameter-entities", false);

        // Prevent loading of external DTDs
        setReaderFeature(reader, "http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
    }

    private void setFactoryFeature(SAXParserFactory factory, String feature, boolean value) {
        try {
            factory.setFeature(feature, value);
        } catch (Exception e) {
            LOG.warn("SAXParserFactory does not support feature {}: {}", feature, e.toString(), e);
        }
    }

    private void setReaderFeature(XMLReader reader, String feature, boolean value) {
        try {
            reader.setFeature(feature, value);
        } catch (Exception e) {
            LOG.warn("XMLReader does not support feature {}: {}", feature, e.toString(), e);
        }
    }

    // other methods
}
