import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.security.Principal;
import java.util.Objects;

/**
 * Utility class that determines whether a self‑update request is allowed.
 *
 * <p>In a production environment the method now performs strict ownership checks
 * and validates that the authenticated user is the same as the user being updated.
 * It also normalises all string comparisons to avoid NPEs and ensures that
 * email changes are only accepted when the user is verified.</p>
 */
public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private final ScimUserProvisioning scimUserProvisioning;

    public ScimUserSelfUpdateAllowed(ScimUserProvisioning scimUserProvisioning) {
        this.scimUserProvisioning = scimUserProvisioning;
    }

    /**
     * Determines whether the incoming request is permitted to update the specified user.
     *
     * @param request the HTTP request containing the update payload
     * @return {@code true} if the request is allowed, {@code false} otherwise
     * @throws IOException if reading the request body fails
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // 1. Verify that the request is authenticated and that the authenticated
        //    principal matches the user ID in the URL path.
        Principal principal = request.getUserPrincipal();
        if (principal == null) {
            // No authenticated user – reject the request
            return false;
        }

        String id = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        // The principal name is expected to be the user ID (or a unique identifier)
        // that matches the SCIM user ID. If it does not match, deny the request.
        if (!Objects.equals(principal.getName(), id)) {
            return false;
        }

        // 2. Read and parse the request body safely
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest;
        try {
            scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);
        } catch (Exception e) {
            // Malformed JSON or missing fields – reject the request
            return false;
        }

        // 3. Retrieve the existing user record
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(id, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // User does not exist – allow creation (handled elsewhere)
            return true;
        }

        // 4. Perform field‑by‑field validation using null‑safe comparisons
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            // Email change is only allowed if the new address is verified
            if (!scimUserFromRequest.isVerified()) {
                return false;
            }
        }

        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }

        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }

        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }

        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        // All checks passed – the request is allowed
        return true;
    }

    // other methods
}
